H=W=20
out=[[0]*W for _ in range(H)]
for r in range(H):
    for c in range(W):
        if c==10 or (r==12 and c>=10):
            out[r][c]=8
        elif c<10:
            d=min(r,H-1-r,c,9-c)
            out[r][c]=2 if d%2==0 else 6
        elif r<12:
            d=min(r,11-r,c-11,19-c)
            out[r][c]=9 if d%2==0 else 1
        else: # r > 12
            d=min(r-13,19-r,c-11,19-c)
            out[r][c]=[7,0,1][d%3]
print('\n'.join(' '.join(map(str,row)) for row in out))
